locals {
  # Datadog exporter block — used in direct (non-downstream) mode
  exporters_direct = {
    "datadog/exporter" = {
      api = {
        site = "datadoghq.com"
        key  = "$${env:DD_API_KEY}"
      }
      sending_queue = {
        enabled = true
        storage = "file_storage/persistent_queue"
      }
    }
  }

  # OTLP downstream exporter block — used when var.downstream_endpoint is set
  exporters_downstream = {
    otlp = {
      endpoint = var.downstream_endpoint
      tls = {
        insecure = true
      }
      sending_queue = {
        enabled    = true
        queue_size = 5000
      }
      retry_on_failure = {
        enabled          = true
        initial_interval = "5s"
        max_interval     = "30s"
        max_elapsed_time = "300s"
      }
    }
  }

  otel_exporters = var.downstream_endpoint == "" ? local.exporters_direct : local.exporters_downstream

  # Pipeline exporter lists swap based on mode
  traces_exporters  = var.downstream_endpoint == "" ? ["datadog/connector", "datadog/exporter"] : ["datadog/connector", "otlp"]
  logs_exporters    = var.downstream_endpoint == "" ? ["datadog/exporter"] : ["otlp"]
  metrics_exporters = var.downstream_endpoint == "" ? ["datadog/exporter"] : ["otlp"]

  otel_config = {
    receivers = {
      otlp = {
        protocols = {
          grpc = {
            endpoint = "0.0.0.0:4317"
          }
          http = {
            endpoint = "0.0.0.0:4318"
          }
        }
      }
    }

    processors = {
      batch = {
        timeout             = "10s"
        send_batch_size     = 10
        send_batch_max_size = 75
      }
    }

    connectors = {
      "datadog/connector" = {}
    }

    exporters = local.otel_exporters

    extensions = {
      health_check = {
        endpoint = "$${env:MY_POD_IP}:13133"
      }
      "file_storage/persistent_queue" = {
        directory = "/var/lib/storage/queue"
      }
    }

    service = {
      extensions = ["health_check", "file_storage/persistent_queue"]
      pipelines = {
        traces = {
          receivers  = ["otlp"]
          processors = []
          exporters  = local.traces_exporters
        }

        logs = {
          receivers  = ["otlp"]
          processors = []
          exporters  = local.logs_exporters
        }

        metrics = {
          receivers  = ["otlp", "datadog/connector"]
          processors = []
          exporters  = local.metrics_exporters
        }
      }
      telemetry = {
        logs = {
          encoding = "json"
        }
      }
    }
  }
}

